// Debounce-Funktion
const debounce = (func, wait) => {
  let timeout;
  return (...args) => {
    clearTimeout(timeout);
    timeout = setTimeout(() => func(...args), wait);
  };
};

// Alert-Komponente
const Alert = React.memo(({ variant = 'error', children }) => {
  const styles = useMemo(() => ({
    bgColor: variant === 'error' ? 'bg-red-50' : 'bg-blue-50',
    textColor: variant === 'error' ? 'text-red-800' : 'text-blue-800',
    borderColor: variant === 'error' ? 'border-red-200' : 'border-blue-200'
  }), [variant]);
  return (
    <div className={`${styles.bgColor} ${styles.textColor} p-4 rounded-lg border ${styles.borderColor} flex items-center justify-center`}>
      {children}
    </div>
  );
});

// Produktkarten-Komponente
const ProductCard = React.memo(({ product, onLike, onDislike, likedProducts = [] }) => {
  const imageUrl = useMemo(() => {
    if (!product.image) return '/placeholder-gift.jpg';
    if (typeof product.image === 'string') {
      if (product.image.includes('src=')) {
        const match = product.image.match(/src="([^"]+)"/);
        return match ? match[1] : '/placeholder-gift.jpg';
      }
      if (product.image.startsWith('http')) return product.image;
      return product.image;
    }
    return '/placeholder-gift.jpg';
  }, [product.image]);

  const handleImageError = useCallback((e) => {
    e.currentTarget.src = '/placeholder-gift.jpg';
  }, []);

  const shopButtonText = product.add_to_cart_text || 'Zum Shop';
  const isLiked = likedProducts.includes(product.id);

  return (
    <div className="bg-white rounded-xl shadow-sm overflow-hidden group transition-all duration-300 hover:shadow-md flex flex-col h-full">
      <div className="relative aspect-square bg-gray-50">
        <a href={product.url} className="block">
          <img
            src={imageUrl}
            alt={product.name}
            width={300}
            height={300}
            srcSet={`${imageUrl} 300w, ${imageUrl}?w=600 600w`}
            sizes="(max-width: 640px) 100vw, 300px"
            loading="lazy"
            decoding="async"
            className="w-full h-full object-cover transition-transform duration-300 group-hover:scale-105"
            onError={handleImageError}
          />
        </a>
        {onLike && (
          <button
            className="absolute top-2 right-2 p-1.5 bg-white rounded-full shadow-sm transition-all duration-200 hover:bg-blue-50"
            aria-label="Zur Wunschliste hinzufügen"
            onClick={() => onLike(product.id)}
          >
            <Heart className={`w-4 h-4 ${isLiked ? 'text-red-500 fill-red-500' : 'text-gray-500'}`} />
          </button>
        )}
      </div>
      <div className="p-4 flex flex-col flex-grow">
        <h3 className="text-base font-medium text-gray-800 line-clamp-2 mb-2 group-hover:text-blue-600">{product.name}</h3>
        <div className="mt-auto flex items-center justify-between gap-2">
          <a
            href={product.url}
            className="text-blue-600 hover:text-blue-800 text-sm font-medium flex items-center"
          >
            Details
            <ChevronRight className="w-4 h-4 ml-1" />
          </a>
          <div className="flex items-center gap-1">
            {onLike && (
              <button
                className="p-1 hover:bg-blue-50 rounded-full transition-colors duration-200"
                onClick={() => onLike(product.id)}
              >
                <ThumbsUp className={`w-4 h-4 ${isLiked ? 'text-blue-600' : 'text-gray-400'}`} />
              </button>
            )}
            {onDislike && (
              <button
                className="p-1 hover:bg-red-50 rounded-full transition-colors duration-200"
                onClick={() => onDislike(product.id)}
              >
                <ThumbsDown className="w-4 h-4 text-gray-400 hover:text-red-500" />
              </button>
            )}
          </div>
          <a
            rel="nofollow"
            target="_blank"
            href={`/redirect.php?product=${product.slug}`}
            className="px-3 py-1 bg-blue-600 text-white text-sm rounded-md hover:bg-blue-700 transition-all duration-200 flex items-center"
            onClick={() => window._paq?.push(['trackEvent', 'Conversion', 'Klick zum Shop', 'Teaser'])}
          >
            {shopButtonText}
            <ChevronRight className="w-4 h-4 ml-1" />
          </a>
        </div>
      </div>
    </div>
  );
});

