// Produkt-Raster-Komponente
const ProductGrid = React.memo(
  ({ products, loading, error, onLike, onDislike, likedProducts, loadMore, hasMore, showMore, setShowMore }) => {
    const observer = useRef();
    const lastProductRef = useCallback(
      (node) => {
        if (loading || !hasMore) return;
        if (observer.current) observer.current.disconnect();
        observer.current = new IntersectionObserver(
          (entries) => {
            if (entries[0].isIntersecting) loadMore();
          },
          { rootMargin: '50px' }
        );
        if (node) observer.current.observe(node);
      },
      [loading, hasMore, loadMore]
    );

    if (loading && !products.length) {
      return (
        <div className="flex items-center justify-center py-12">
          <Loader2 className="w-8 h-8 text-blue-600 animate-spin mr-2" />
          <span className="text-gray-600">Lade Produkte...</span>
        </div>
      );
    }

    if (error) return <Alert>{error}</Alert>;

    if (!products.length) {
      return (
        <div className="text-center py-12 bg-gray-50 rounded-xl">
          <Package className="w-12 h-12 text-gray-300 mx-auto mb-2" />
          <p className="text-gray-600 font-medium">Keine Produkte gefunden</p>
        </div>
      );
    }

    const initialProducts = products.slice(0, 8);

    return (
      <div>
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          {(showMore ? products : initialProducts).map((p, index) => (
            <div
              key={p.id}
              ref={index === (showMore ? products.length : initialProducts.length) - 1 ? lastProductRef : null}
            >
              <ProductCard
                product={p}
                onLike={onLike}
                onDislike={onDislike}
                likedProducts={likedProducts}
              />
            </div>
          ))}
        </div>
        {!showMore && products.length > 8 && setShowMore && (
          <div className="mt-6 text-center">
            <button
              onClick={() => setShowMore(true)}
              className="px-4 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700 transition-all duration-200 flex items-center mx-auto"
            >
              <Sparkles className="w-4 h-4 mr-1" />
              Mehr anzeigen
            </button>
          </div>
        )}
        {loading && showMore && (
          <div className="py-6 text-center">
            <Loader2 className="w-6 h-6 text-blue-600 animate-spin mx-auto" />
          </div>
        )}
      </div>
    );
  }
);

